func LeUint(a, b uint) bool     { return a <= b }
func GtUint(a, b uint) bool     { return a > b }
func GeUint(a, b uint) bool     { return a >= b }
func EqUint(a, b uint) bool     { return a == b }
func NeUint(a, b uint) bool     { return a != b }
func NegUint(a uint) uint       { return -a }
func NotUint(a uint) uint       { return ^a }
func IncUint(a uint) uint {
	a++
	return a
}
func DecUint(a uint) uint {
	a--
	return a
}
func ShlUint(a uint, n uint) uint { return a << n }
func ShrUint(a uint, n uint) uint { return a >> n }
func ShlSUint(a uint, n int) uint { return a << n }
func ShrSUint(a uint, n int) uint { return a >> n }
func CompoundUint(a, b uint) uint {
	a += b
	a *= b
	a -= 3
	a ^= b
	a |= 1
	a &= ^b | 0x55
	a &^= 2
	a <<= 1
	a >>= 2
	if b != 0 {
		a /= b
		a %= b
	}
	return a
}
func ConvUintToI8(x uint) int8      { return int8(x) }
func ConvUintToI16(x uint) int16    { return int16(x) }
func ConvUintToI32(x uint) int32    { return int32(x) }
func ConvUintToI64(x uint) int64    { return int64(x) }
func ConvUintToInt(x uint) int      { return int(x) }
func ConvUintToU8(x uint) uint8     { return uint8(x) }
func ConvUintToU16(x uint) uint16   { return uint16(x) }
func ConvUintToU32(x uint) uint32   { return uint32(x) }
func ConvUintToU64(x uint) uint64   { return uint64(x) }
func ConvUintToUint(x uint) uint    { return uint(x) }
func ConvUintToUptr(x uint) uintptr { return uintptr(x) }

